\end{theorem}

\begin{proof}
\leanok
  The relative Picard functor \(\Pic^\sharp_{C/k}\) of
  \cref{def:rel_pic_sharp} is abelian-group valued, with sum
  \([\mathcal{L}] + [\mathcal{M}] = [\mathcal{L} \otimes \mathcal{M}]\),
